use std::{fs, path::Path};
fn replace_between(source:&mut String,start:&str,end:&str,replacement:&str,label:&str){let sc=source.matches(start).count();assert_eq!(sc,1,"compact meter patch {label} start expected one match, found {sc}");let begin=source.find(start).expect("compact meter start anchor");let finish=source[begin..].find(end).map(|o|begin+o).expect("compact meter end anchor");source.replace_range(begin..finish,replacement);}
pub fn run(out:&Path){let path=out.join("feature_overlays_v170_fixed.rs");let mut source=fs::read_to_string(&path).expect("read generated feature overlay").replace("\r\n","\n");
replace_between(&mut source,r#"unsafe fn overlay_help(hwnd:HWND,state:&State,x:i32,y:i32)->Option<String>{"#,r#"

#[cfg(test)]
mod v1165_consumable_overlay_tests"#,r#"unsafe fn overlay_help(hwnd:HWND,state:&State,x:i32,y:i32)->Option<String>{
    if state.collapsed{return Some("Click, Enter or Space to expand".into());}let rc=logical_client_rect(hwnd,state.scale_percent);if y<TOOLBAR_H{let button=if state.kind==Kind::Dps{dps_toolbar_button_w(rc.right,dps_layout_scale(state))}else{BUTTON_W};if state.kind==Kind::Dps&&state.compact_mode{if x>=rc.right-button{return Some("Hide overlay • restore from tray or Ctrl+Shift+F10".into());}let mode=compact_mode_rect();if x>=mode.left&&x<mode.right{return Some("Damage / Heal / Tank".into());}for item in toolbar_items(state,rc.right){if x>=item.rect.left&&x<item.rect.right{return Some(toolbar_action_help(item.action).into());}}return Some("Compact combat meter".into());}if x>=rc.right-button{return Some("Hide overlay • restore from tray or Ctrl+Shift+F10".into());}if x>=rc.right-button*2{return Some("Collapse to the configured screen edge".into());}if x>=rc.right-button*3{return Some("Open overlay settings".into());}if state.kind==Kind::Dps{for item in toolbar_items(state,rc.right){if x>=item.rect.left&&x<item.rect.right{return Some(toolbar_action_help(item.action).into());}}}return Some(toolbar_title(state));}
    if state.kind==Kind::Dps{if !state.compact_mode&&hover_badge_at(hwnd,state,x,y).is_some(){return None;}if !state.compact_mode{let target_top=TOOLBAR_H+4;if y>=target_top&&y<target_top+27{return Some("Target context • name/ID, live HP, Enrage / Power Seal timer and encounter time".into());}let tabs_top=TOOLBAR_H+35;if y>=tabs_top&&y<tabs_top+23{return Some("Damage / Heal / Tank • keyboard 1 / 2 / 3".into());}}if let Some(row)=dps_row_at(hwnd,state,y){return Some(if state.compact_mode{format!("{} • active rate • click to inspect",row.name)}else{format!("{} • Total / Active / Share • Click to inspect",dps_identity(&row))});}}else{let(_,_,top)=mechanics_scroll_metrics(state,rc.bottom);if y>=top{let index=state.scroll+((y-top)/MECH_ROW_H)as usize;let rows=ordered_mechanic_rows(state,now_ms());if let Some(row)=rows.get(index){return Some(match row{MechanicDisplayRow::Tracker(row)=>format!("{} • {}",row.label,row.detail),MechanicDisplayRow::Mechanic(row)=>format!("{} {}",row.label,row.target.as_deref().unwrap_or(""))});}}}None
}
"#,"overlay help semantic");
replace_between(&mut source,r#"// ---- v1.22.0 compact Raid Mode -------------------------------------------------"#,r#"fn raid_consumable_color"#,r#"// ---- v1.22.0 compact Raid Mode -------------------------------------------------
const RAID_ROWS_PER_COLUMN:usize=10;
const RAID_MAX_ROWS:usize=20;
const RAID_BASE_WIDTH:i32=1080;
const RAID_CENTER_GAP:i32=76;
const RAID_FS_YELLOW_MS:i64=120_000;
const RAID_FS_RED_MS:i64=30_000;
#[derive(Clone,Copy)]struct RaidWindowState{active:bool,normal:RECT,raid:RECT,has_raid:bool,entry_compact:bool}
std::thread_local!{static RAID_WINDOWS:std::cell::RefCell<std::collections::HashMap<isize,RaidWindowState>>=std::cell::RefCell::new(std::collections::HashMap::new());}
fn raid_key(state:&State)->isize{state as *const State as isize}
fn raid_active(state:&State)->bool{RAID_WINDOWS.with(|items|items.borrow().get(&raid_key(state)).map(|v|v.active).unwrap_or(false))}
fn raid_layout_path(state:&State)->std::path::PathBuf{state.paths.root.join("dps-raid-layout.txt")}
fn raid_rect_valid(r:RECT)->bool{r.right-r.left>=300&&r.bottom-r.top>=140}
fn raid_load_rect(hwnd:HWND,state:&State)->Option<RECT>{let text=std::fs::read_to_string(raid_layout_path(state)).ok()?;let values:Vec<i32>=text.split_whitespace().filter_map(|v|v.parse().ok()).collect();if values.len()!=4&&values.len()!=5{return None;}let saved_scale=if values.len()==5{values[4].clamp(50,200)}else{state.scale_percent.clamp(50,200)};let current_scale=state.scale_percent.clamp(50,200);let width=((values[2]as i64)*(current_scale as i64)/(saved_scale as i64)).clamp(1,i32::MAX as i64)as i32;let height=((values[3]as i64)*(current_scale as i64)/(saved_scale as i64)).clamp(1,i32::MAX as i64)as i32;let r=RECT{left:values[0],top:values[1],right:values[0].saturating_add(width),bottom:values[1].saturating_add(height)};if !raid_rect_valid(r){return None;}Some(crate::ui::fit_rect(r,unsafe{crate::ui::work_area(hwnd)}))}
fn raid_save_rect_file(state:&State,r:RECT){if !raid_rect_valid(r){return;}let text=format!("{} {} {} {} {}\n",r.left,r.top,(r.right-r.left).max(1),(r.bottom-r.top).max(1),state.scale_percent.clamp(50,200));if let Err(err)=std::fs::write(raid_layout_path(state),text){crate::logging::write(format!("raid layout: save failed: {err}"));}}
fn raid_store_rect(state:&State,r:RECT){if !raid_rect_valid(r){return;}RAID_WINDOWS.with(|items|{let mut items=items.borrow_mut();let key=raid_key(state);let entry=items.entry(key).or_insert(RaidWindowState{active:true,normal:r,raid:r,has_raid:true,entry_compact:state.compact_mode});entry.raid=r;entry.has_raid=true;});if !state.compact_mode{raid_save_rect_file(state,r);}save_meter_view_size(state,r);}
fn raid_auto_rect(hwnd:HWND,state:&State,normal:RECT)->RECT{let scale=dps_layout_scale(state);let logical_h=dps_rows_top_for(state)+RAID_ROWS_PER_COLUMN as i32*dps_row_h_for(state,scale)+8;let base_w=if state.compact_mode{760}else{RAID_BASE_WIDTH};let target_w=scale_px(base_w,state.scale_percent).max(overlay_min_width_mode(Kind::Dps,state.scale_percent,state.compact_mode));let target_h=scale_px(logical_h,state.scale_percent).max(overlay_min_height_mode(Kind::Dps,state.scale_percent,state.compact_mode));let work=unsafe{crate::ui::work_area(hwnd)};let ax=preferred_axis_anchor(normal.left,normal.right,work.left,work.right);let ay=preferred_axis_anchor(normal.top,normal.bottom,work.top,work.bottom);anchored_scaled_rect(normal,work,target_w,target_h,ax,ay)}
unsafe fn toggle_raid_mode(hwnd:HWND,state:&mut State){if state.kind!=Kind::Dps||state.collapsed{return;}let mut current:RECT=std::mem::zeroed();if GetWindowRect(hwnd,&mut current)==0{return;}let key=raid_key(state);let active=raid_active(state);if !active{persist_overlay_rect(state,current);let file=read_meter_view(&state.paths);let mode_saved=restored_meter_size(meter_view_size(&file,state.compact_mode,true),state.scale_percent).map(|(w,h)|{let work=crate::ui::work_area(hwnd);let ax=preferred_axis_anchor(current.left,current.right,work.left,work.right);let ay=preferred_axis_anchor(current.top,current.bottom,work.top,work.bottom);anchored_scaled_rect(current,work,w,h,ax,ay)});let legacy=if state.compact_mode{None}else{RAID_WINDOWS.with(|items|items.borrow().get(&key).copied()).and_then(|v|v.has_raid.then_some(v.raid)).or_else(||raid_load_rect(hwnd,state))};let target=mode_saved.or(legacy).filter(|r|raid_rect_valid(*r)).unwrap_or_else(||raid_auto_rect(hwnd,state,current));RAID_WINDOWS.with(|items|{items.borrow_mut().insert(key,RaidWindowState{active:true,normal:current,raid:target,has_raid:true,entry_compact:state.compact_mode});});state.expanded=target;state.scroll=0;SetWindowPos(hwnd,HWND_TOPMOST,target.left,target.top,(target.right-target.left).max(1),(target.bottom-target.top).max(1),SWP_NOACTIVATE);}else{persist_overlay_rect(state,current);let entry=RAID_WINDOWS.with(|items|items.borrow().get(&key).copied());let fallback=entry.map(|v|v.normal).unwrap_or(current);let target=if entry.map(|v|v.entry_compact==state.compact_mode).unwrap_or(false){fallback}else{let file=read_meter_view(&state.paths);restored_meter_size(meter_view_size(&file,state.compact_mode,false),state.scale_percent).map(|(w,h)|{let work=crate::ui::work_area(hwnd);let ax=preferred_axis_anchor(fallback.left,fallback.right,work.left,work.right);let ay=preferred_axis_anchor(fallback.top,fallback.bottom,work.top,work.bottom);anchored_scaled_rect(fallback,work,w,h,ax,ay)}).unwrap_or(fallback)};RAID_WINDOWS.with(|items|{if let Some(v)=items.borrow_mut().get_mut(&key){v.active=false;v.raid=current;v.has_raid=true;}});state.expanded=target;state.scroll=0;SetWindowPos(hwnd,HWND_TOPMOST,target.left,target.top,(target.right-target.left).max(1),(target.bottom-target.top).max(1),SWP_NOACTIVATE);}sync_consumable_popup(hwnd,state);InvalidateRect(hwnd,null(),0);if !state.consumable_hwnd.is_null(){InvalidateRect(state.consumable_hwnd,null(),0);}}

"#,"raid compact sizing");
fs::write(path,source).expect("write compact meter generated overlay");}
